/**
 * Session distillation: selecting what a finished conversation produced.
 *
 * The distinction this module exists to make: turn capture stores the
 * conversation stream without choosing anything, and it was all the plugin ever
 * did. That records a dialogue, not a conclusion. Distillation looks at a finished
 * turn and asks the judgment layer which parts a future session would be wrong
 * without.
 *
 * Three constraints define the design, all of them deliberate:
 *
 * 1. Candidates are cut HERE, by the plugin, never generated by the model. A narrow
 *    judgment model picks among options; asking it to write a summary would trade
 *    its strength (choosing) for a task the main model does better.
 * 2. Distillation selects, it does not rewrite. What lands in memory is the
 *    candidate's own words.
 * 3. Total failure must not lose partial success. If one candidate's write fails,
 *    the ones already written stay written, and the failure is reported.
 *
 * Retrieval path: `retention-router.mjs` decides WHERE a fact goes; this module
 * decides WHAT is worth sending there. Both write through the same store, which is
 * why an explicit "remember this" and an automatic distillation of the same fact
 * converge instead of duplicating: the key comes from the fact, not the source.
 */
import { createHash } from 'node:crypto';
import { sessionDistill } from './decision-points.mjs';
import { residentDigestOf } from './memory-landings.mjs';
import { questionStages } from './decision-executor.mjs';

/** A declaration's question in the wire shape the transport expects. */
const toQuestion = question => ({ type: 'choice', instructions: question.instructions, criteria: question.criteria });

/** Upper bound on candidates presented to one judgment.
 *
 * The judged-state character cap already bounds each candidate; this bounds HOW
 * MANY. A long state dilutes the criteria — that is exactly what the cap exists
 * for — so a turn producing forty sentences is judged on its most promising few
 * rather than all of them.
 */
export const MAX_CANDIDATES = 8;

/** A candidate must be at least this long to be worth a judgment slot. */
const MIN_CANDIDATE_CHARS = 12;

/** Markers that mean "this line is not a conclusion", whatever its wording. */
const NOISE = /^(?:ok(?:ay)?|yes|no|sure|好|好的|嗯|对|是|收到|明白|谢谢|thanks|thank you|lgtm|looks good|done|完成|已确认|got it|收到👌)[.。！!~～\s]*$/i;

/**
 * Cut a finished turn into candidates.
 *
 * Cutting is by speaker and sentence, and the user's words are preferred: a fact
 * the user stated is the user's fact, while the assistant's restatement of it is a
 * second-hand copy that may already be paraphrased. Assistant text is not excluded
 * outright, because a turn's conclusion is often the assistant's summary of what
 * was decided — but it is only kept when the user did not say the same thing.
 */
export function cutCandidates({ userText = '', assistantText = '', reason } = {}) {
  const candidates = [];
  const seen = new Set();
  const push = (text, speaker) => {
    const clean = normalize(text);
    if (clean.length < MIN_CANDIDATE_CHARS) return;
    if (NOISE.test(clean)) return;
    const fingerprint = clean.toLocaleLowerCase('en-US').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
    if (!fingerprint || seen.has(fingerprint)) return;
    seen.add(fingerprint);
    candidates.push({ id: `c${candidates.length}`, text: clean, speaker });
  };
  // Sentences, not paragraphs: a paragraph containing one conclusion and three
  // pleasantries should yield the conclusion, not be discarded wholesale.
  for (const sentence of sentences(userText)) push(sentence, 'user');
  if (reason !== 'error' && reason !== 'aborted') for (const sentence of sentences(assistantText)) push(sentence, 'assistant');
  return candidates.slice(0, MAX_CANDIDATES);
}

function normalize(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** Split text into sentences across the scripts this plugin actually sees. */
function sentences(text) {
  const source = String(text ?? '');
  if (!source.trim()) return [];
  // Keep fenced code out: a code block is usually a tool result restated, and it
  // eats the character budget a conclusion needs.
  const withoutCode = source.replace(/```[\s\S]*?```/g, ' ');
  return withoutCode
    .split(/(?<=[.。！？!?;；])\s+|\n+/)
    .map(part => part.trim())
    .filter(Boolean);
}

/**
 * A stable key for a distilled fact.
 *
 * The ticket is explicit that a content hash is the wrong key here: correcting a
 * stored fact would create a second entry rather than replace the first, and
 * correction is the most common way a remembered fact changes. So the key is
 * derived from the SCOPE plus the fact's leading subject — enough to collide on a
 * correction ("port is 8080" → "port is 9090" keeps the key) and distinct across
 * different facts.
 *
 * When the judgment names a key explicitly, that wins: a declaration may require it
 * to reuse a key already present in resident memory.
 */
export function factKey({ scope, text, explicit }) {
  if (typeof explicit === 'string' && /^[a-zA-Z0-9._:-]{1,120}$/.test(explicit)) return explicit;
  const tokens = normalize(text).toLocaleLowerCase('en-US')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim().split(' ').filter(Boolean);
  // The KEY is the SUBJECT, which is the part that stays put when a fact is
  // corrected: "port is 8080" → "port is 9090" must collide, because that is one
  // fact whose value changed. So the value-bearing tail is dropped rather than
  // hashed — a bare leading-words hash kept the number and produced a second entry,
  // which is the exact failure the ticket warned a content hash would cause.
  // Verbs that often precede the value are dropped wherever they sit.
  const VALUE_WORDS = new Set(['是', '为', 'is', 'are', 'was', 'were', '=', '改为', '换成', 'uses', 'use', 'requires', '需要']);
  const subject = tokens.filter(token => !VALUE_WORDS.has(token) && !/^\d/.test(token));
  const canonical = (subject.length ? subject : tokens).slice(0, 4).join('-') || 'fact';
  return `${createHash('sha256').update(`${scope}:${canonical}`).digest('hex').slice(0, 12)}`;
}

/** Keys already present in resident memory, so a distillation can reuse one. */
export function residentKeys(resident) {
  const keys = new Set();
  for (const value of Object.values(resident ?? {})) {
    if (typeof value !== 'string') continue;
    for (const match of value.matchAll(/<!--\s*id:\s*([a-zA-Z0-9._:-]{1,120})\s*-->/g)) keys.add(match[1]);
  }
  return [...keys];
}

/**
 * Where a distilled candidate belongs.
 *
 * The targets are resident-memory targets (`RESIDENT_TARGETS`), not memory scopes:
 * distillation writes into the always-visible files, and `external` is the fallback
 * when they are full. The choice uses only the identity the session actually has — an
 * earlier version asked a fabricated session with an empty cwd whether a project
 * existed, which answered "no" for every session and sent every repository fact to
 * global memory.
 */
export function pickDistillTarget({ candidate, identity }) {
  const text = candidate?.text ?? '';
  const hasProject = Boolean(identity?.projectId || identity?.projectPath);
  if (!hasProject) return 'user';
  // A fact about this repository belongs to the project file; anything else is about
  // the user across projects.
  // `\b` is a word boundary for ASCII only, so `\b项目\b` never matches Chinese —
  // every CJK repository fact fell through to global memory. Match the Latin words on
  // a boundary and the CJK words without one.
  return /\b(?:project|repo(?:sitory)?)\b|这(?:个)?(?:项目|仓库)|代码库/i.test(text) ? 'project-memory' : 'global-memory';
}

/** Whether an error means the resident file is full, which must degrade to the
 * external store rather than lose the fact. */
export const isResidentFull = error => /exceeds limit/i.test(error instanceof Error ? error.message : String(error ?? ''));

/**
 * Run distillation over one finished turn.
 *
 * Returns a report rather than throwing: a distillation that fails is worth a log
 * line, never a failed turn, because it runs after the answer the user is waiting
 * for. Partial success is reported honestly — `retained` lists what landed,
 * `failed` what did not.
 */
export async function distillTurn({
  turn, decideBatch, candidates, resident = {}, retain, now = () => Date.now(), maxCandidates = MAX_CANDIDATES,
  point = sessionDistill,
}) {
  const startedAt = now();
  const cut = candidates ?? cutCandidates(turn);
  const report = { startedAt, candidates: cut.length, retained: [], failed: [], gate: 'discarded', durationMs: 0 };
  if (!cut.length) { report.durationMs = now() - startedAt; report.reason = 'no-candidates'; return report; }

  // The two levels come from the DECLARATION's own structure: `questionStages` returns
  // the gate first and the candidate selection second, because that is what
  // `questionDepends` says. Deriving the split here rather than hard-coding two blocks
  // is what keeps the declaration authoritative when a user re-orders or edits it.
  const stages = questionStages(point);
  const gateNames = stages[0] ?? [];
  const hasSecondLevel = stages.length > 1;
  const keys = residentKeys(resident);
  // One projection of resident memory, shared with the memory path — a second copy
  // here is how two views of "what is already stored" start disagreeing.
  const residentDigest = residentDigestOf(resident)?.text;
  // Two levels, and the first is one question about the whole turn. It exists to
  // stop most turns here: judging every candidate on a turn that said nothing
  // durable spends the budget to learn nothing.
  let gate;
  try {
    gate = await decideBatch({
      state: {
        candidates: cut.map(candidate => candidate.text),
        ...(residentDigest ? { residentDigest } : {}),
      },
      // The gate question comes from the DECLARATION. Restating its criteria here
      // would recreate the exact bug this work exists to remove — three drifted
      // copies of one judgment, with no way to know which one is in effect.
      questions: Object.fromEntries(gateNames.map(name => [name, toQuestion(point.questions[name])])),
    });
  } catch (error) {
    report.durationMs = now() - startedAt;
    report.reason = 'gate-failed';
    report.error = error instanceof Error ? error.message : String(error);
    return report;
  }
  // `decideBatch` returns a map of question name to chosen option. Accept a bare
  // string too, because a caller wiring this to a transport may reasonably drop the
  // envelope once it has validated the choice.
  const gateChoice = name => typeof gate?.[name] === 'string' ? gate[name] : gate?.[name]?.choice;
  const gateAnswer = gateChoice(gateNames[0]);
  // `store` is what the declaration says this answer authorizes; anything else means
  // the turn is not worth the second level. Read the verb rather than hard-coding the
  // option name, so a user's edited declaration governs the branch.
  if (!hasSecondLevel || point.actions?.[gateNames[0]]?.[gateAnswer] !== 'store') {
    // Discarding is the common and correct answer, not a failure: report the
    // duration so a reader can see the gate is cheap when it says no.
    report.durationMs = now() - startedAt;
    return report;
  }
  report.gate = 'keep';

  // Second level: every candidate in ONE request. Measured cost of several
  // questions about one subject is nearly flat, so per-candidate round trips would
  // pay the latency several times over for the same answers.
  // Per-candidate questions reuse the declaration's `candidate_selection` criteria
  // verbatim; only the instruction names which candidate this instance is about.
  const selectionQuestion = point.questions.candidate_selection;
  const questions = {};
  for (const candidate of cut) {
    questions[`candidate_${candidate.id}`] = {
      type: 'choice',
      instructions: `${selectionQuestion.instructions} This question is about candidate ${candidate.id}.`,
      criteria: selectionQuestion.criteria,
    };
  }
  let selection;
  try {
    selection = await decideBatch({
      state: {
        candidates: cut.map(candidate => candidate.text),
        ...(residentDigest ? { residentDigest } : {}),
        ...(keys.length ? { existingKeys: keys.slice(0, 40) } : {}),
      },
      questions,
    });
  } catch (error) {
    report.durationMs = now() - startedAt;
    report.reason = 'selection-failed';
    report.error = error instanceof Error ? error.message : String(error);
    return report;
  }

  const picked = name => typeof selection?.[name] === 'string' ? selection[name] : selection?.[name]?.choice;
  const chosen = cut.filter(candidate => picked(`candidate_${candidate.id}`) === 'retain');
  if (!chosen.length) { report.durationMs = now() - startedAt; report.reason = 'nothing-selected'; return report; }

  for (const candidate of chosen) {
    const evidence = { eventId: `distill:${candidate.id}`, quote: candidate.text };
    try {
      // The key is derived for the target the fact will land in, so the same fact
      // distilled into a different store is a different row — and a corrected fact in
      // the SAME store collides, which is what makes a correction replace.
      const saved = await retain({ candidate, evidence, resident });
      report.retained.push({ id: candidate.id, target: saved?.target, degraded: saved?.status === 'degraded' });
    } catch (error) {
      // One failed candidate must not discard the ones already written.
      report.failed.push({ id: candidate.id, reason: reasonOf(error) });
      // The most common failure here is a full resident file. Degrading to the
      // external store is what keeps the fact instead of losing it.
      if (isResidentFull(error)) {
        try {
          const saved = await retain({ candidate, evidence, resident, forceExternal: true });
          report.retained.push({ id: candidate.id, target: saved?.target, degraded: true });
          report.failed.pop();
        } catch (fallbackError) {
          report.failed.push({ id: candidate.id, reason: reasonOf(fallbackError) });
        }
      }
    }
  }
  report.durationMs = now() - startedAt;
  return report;
}

function reasonOf(error) {
  const text = error instanceof Error ? error.message : String(error ?? '');
  if (!text) return 'unknown';
  if (/exceeds limit/i.test(text)) return 'resident-full';
  if (/revision conflict/i.test(text)) return 'revision-conflict';
  if (/evidence/i.test(text)) return 'evidence-mismatch';
  return 'write-failed';
}

/**
 * The distillation trigger policy.
 *
 * Two signals, and neither is a timer:
 *
 * - Archiving a session is the user saying "this conversation is over". It is the
 *   strongest signal available and the only one that can be awaited before the
 *   archive is written.
 * - A turn threshold is the weaker fallback for a conversation that is never
 *   archived. Without it, closing the browser loses everything since the last
 *   archive — which is every conversation that was never explicitly ended.
 *
 * No idle timer: the platform has no idle event, and maintaining one costs more in
 * complexity than it buys. That choice is recorded here because it looks like an
 * omission otherwise.
 */
export function createDistillTrigger({ threshold = 8, enabled = () => true } = {}) {
  const turns = new Map();
  const archived = new Set();
  return Object.freeze({
    /** Count one finished turn; report whether the threshold fired. */
    countTurn(sessionId, { durable = true } = {}) {
      if (!enabled() || !durable || archived.has(sessionId)) return false;
      const next = (turns.get(sessionId) ?? 0) + 1;
      const limit = Number.isSafeInteger(threshold) && threshold > 0 ? threshold : 0;
      if (limit && next >= limit) { turns.set(sessionId, 0); return true; }
      turns.set(sessionId, next);
      return false;
    },
    /** Mark a session archived so the threshold stops re-firing for it. */
    markArchived(sessionId) { archived.add(sessionId); turns.delete(sessionId); },
    /** Arm the archive path: the archive will run a distillation for this session. */
    isArchived(sessionId) { return archived.has(sessionId); },
    forget(sessionId) { turns.delete(sessionId); archived.delete(sessionId); },
    turnCount(sessionId) { return turns.get(sessionId) ?? 0; },
  });
}
